4	
5	/**
6	 * Hell/Dunkel-Umschalter, sitzt in der Top-Bar (src/frontend/app/page.tsx) hinter
7	 * dem CSV-Export-Button. Die Startklasse setzt schon ein kleines Inline-Script in
8	 * layout.tsx, bevor React überhaupt rendert — der Lese-Zugriff auf document hier
9	 * im useState-Initializer (statt in einem Effect) übernimmt diesen Stand direkt,
10	 * ohne einen zweiten Render auszulösen. `suppressHydrationWarning` erlaubt, dass
11	 * sich das Icon-Zeichen vom serverseitigen "🌙" unterscheidet, falls der Browser
12	 * bereits Dunkel gespeichert hat.
13	 */
14	export function ThemeToggle() {
15	  const [isDark, setIsDark] = useState(
16	    () => typeof document !== "undefined" && document.documentElement.classList.contains("dark"),
17	  );
18	
19	  function toggle() {
20	    const next = !isDark;
21	    setIsDark(next);
22	    document.documentElement.classList.toggle("dark", next);
23	    try {
24	      localStorage.setItem("theme", next ? "dark" : "light");
25	    } catch {
26	      // Privater Modus o.ä.: Umschalten funktioniert trotzdem, bleibt nur nicht gespeichert.
27	    }
28	  }
29	
30	  return (
31	    <button
32	      type="button"
33	      onClick={toggle}
34	      aria-label={isDark ? "Switch to light theme" : "Switch to dark theme"}
35	      title={isDark ? "Switch to light theme" : "Switch to dark theme"}
36	      className="flex h-9 w-9 items-center justify-center rounded-full border border-zinc-300 bg-surface text-base text-zinc-700 shadow-sm transition hover:bg-zinc-100 dark:border-zinc-700 dark:text-zinc-200 dark:hover:bg-zinc-800"
37	    >
38	      <span suppressHydrationWarning>{isDark ? "☀" : "🌙"}</span>
39	    </button>
40	  );
41	}
